const i=[{id:"C01",title:"WHO · Stress: Fragen und Antworten",url:"https://www.who.int/news-room/questions-and-answers/item/stress",type:"guidance",finding:"Beschreibt Stress als Sorge oder innere Anspannung in schwierigen Situationen. Empfiehlt Alltagstruktur, Ruhe, passende Bewegung, vertraute Kontakte und einen bewussten Umgang mit Nachrichten.",limitation:"Allgemeine Empfehlungen, kein gemessener ODA-Effekt. Vorschläge müssen zur Person passen. Sie beseitigen nicht jeden Stressauslöser und ersetzen keine Versorgung."},{id:"C02",title:"NHS · Hilfe bei Stress",url:"https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/stress/",type:"guidance",finding:"Stress kann mit körperlichen, gedanklichen, emotionalen und verhaltensbezogenen Anzeichen einhergehen. Suche fachliche Unterstützung, wenn du schwer zurechtkommst oder Selbsthilfe nicht hilft.",limitation:"Anspannung, Kopfschmerzen oder Konzentrationsprobleme erklären ihre Ursache nicht. Neue oder beunruhigende Beschwerden können Abklärung brauchen. Benennen ist keine Diagnose."},{id:"C03",title:"NHS Every Mind Matters · Angst",url:"https://www.nhs.uk/every-mind-matters/mental-health-issues/anxiety/",type:"guidance",finding:"Empfiehlt, sich sicheren gefürchteten Situationen schrittweise zu stellen, Auslöser festzuhalten und bei beeinträchtigendem Alltag Hilfe zu suchen. Atemnot kann andere Ursachen haben.",limitation:"Allgemeine Empfehlungen erklären nicht jede gefürchtete Situation für sicher und bestätigen ODA nicht als Expositionsbehandlung. Gewalt oder echte Gefahr zu verlassen schützt dich."},{id:"C04",title:"NHS · Panikstörung",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Wiederholte Panikattacken brauchen fachliche Abklärung. Ähnliche körperliche Beschwerden können bei anderen Erkrankungen auftreten. Behandlung kann kognitive Verhaltenstherapie und verordnete Medikamente umfassen.",limitation:"Neue Brustschmerzen, ein Gefühl drohender Ohnmacht oder Atemnot sind nicht automatisch harmlose Panik. Atmen allein behandelt keine Panikstörung. Medikamentenentscheidungen gehören zur behandelnden Fachperson."},{id:"C05",title:"NHS · 2026 · Atemübungen bei Stress",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/breathing-exercises-for-stress/",type:"guidance",finding:"Empfiehlt regelmäßiges, sanftes Atmen ohne Zwang in einer bequem gestützten Haltung. Zählen ist optional und soll nicht anstrengend sein.",limitation:"Allgemeine Empfehlungen ohne isolierten Studieneffekt, optimales Verhältnis oder Garantie. Sanftes Atmen unterscheidet sich vom untersuchten doppelten Einatmen. Kürzere ODA-Pausen sind Anpassungen."},{id:"C06",title:"NHS · Zehn Anregungen gegen Stress",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/tips-to-reduce-stress/",type:"guidance",finding:"Passende Bewegung und vertraute Kontakte können beim Umgang mit Stress helfen. Weniger intensive Gefühle bedeuten nicht, dass die belastende Situation verschwunden ist.",limitation:"Empfehlungen ohne eigenständigen bezifferten Wirksamkeitsbeleg. Anderen zu helfen passt möglicherweise nicht bei Überlastung. Eine Kontaktliste ohne Bitte belegt keine erhaltene Unterstützung."},{id:"C07",title:"Singh et al. · 2023 · Überblick über Forschungsübersichten zu Bewegung",url:"https://www.newswise.com/pdf_docs/167719499939215_Singh%20et%20al%202023.pdf",type:"research",finding:"97 Übersichten umfassten 1.039 unterschiedliche Einzelstudien. Bei Depression lag die mediane SMD bei −0,43 (IQR −0,66 bis −0,27), bei Angst bei −0,42 (−0,66 bis −0,26). Belastung: SMD −0,60 (95%-Konfidenzintervall −0,78 bis −0,42) aus einer Übersicht mit sechs Studien.",limitation:"77 Übersichten hatten kritisch niedrige Qualität. Berichtete Teilnehmerzahlen überschneiden sich. Mediane und IQR sind keine zusammengefassten Effekte oder Konfidenzintervalle. Zusammenhänge in Intensitäts- und Dauerteilgruppen bestimmen keine persönliche Dosis und sagen nicht die Wirkung eines Spaziergangs voraus."},{id:"C08",title:"Fincham et al. · 2023 · Meta-Analyse zu Atemübungen",url:"https://doi.org/10.1038/s41598-022-27247-y",type:"research",finding:"Die Hauptanalyse zu Stress kombinierte 12 randomisierte Studien mit 785 Erwachsenen: Hedges’ g −0,35 (95%-Konfidenzintervall −0,55 bis −0,14). Techniken und untersuchte Personen unterschieden sich.",limitation:"Mittleres Verzerrungsrisiko und begrenzte Nachbeobachtung schränken Vertrauen ein. Teilgruppenbefunde zeigen weder die Überlegenheit langsamen Atmens noch ein optimales Protokoll, Gleichwertigkeit mit Behandlung oder gleiche Sicherheit schneller und langsamer Techniken."},{id:"C09",title:"Webb, Miles & Sheeran · 2012 · Meta-Analyse zur Emotionsregulation",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"306 experimentelle Vergleiche fanden im Durchschnitt Perspektivwechsel d+ 0,45, Neubewertung des Auslösers 0,36 und Gedankenunterdrückung −0,12.",limitation:"Nur die Zusammenfassung zugänglich; hauptsächlich kurzfristig erzeugte Gefühle im Labor. Gedanken- und Ausdrucksunterdrückung unterscheiden sich. Kein Beleg, dass Unterdrückung immer scheitert, eine tröstliche Deutung wahr ist oder ODA-Hinweise dauerhaft helfen."},{id:"C10",title:"NHS Every Mind Matters · Unhilfreiche Gedanken anders betrachten",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/",type:"guidance",finding:"Empfiehlt, einen Gedanken zu bemerken, Belege zu prüfen und eine ausgewogenere Möglichkeit zu erwägen. Reale Schwierigkeiten können Problemlösen, Akzeptanz oder Unterstützung brauchen.",limitation:"Empfehlungen, keine Studie zum verkürzten ODA-Arbeitsblatt. Ausgewogenheit darf Unsicherheit enthalten. Positive Deutungen brauchen Belege und dürfen schlechte Behandlung nicht verharmlosen."},{id:"C11",title:"Balban et al. · 2023 · Studie zu strukturierten Atemübungen",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 Erwachsene wurden zufällig fünf täglichen Minuten Atemübung oder Achtsamkeit über 28 Tage zugeteilt. Die Atemgruppen zusammen verbesserten positive Gefühle durchschnittlich um 1,91 Punkte gegenüber 1,22; zyklisches Seufzen schnitt im Modell günstiger als Achtsamkeit ab. Angst besserte sich ohne signifikanten Gruppenunterschied.",limitation:"Kleine Gruppen, medizinische/psychiatrische Ausschlüsse, nachträgliche Registrierung und kein bestätigtes Konfidenzintervall zwischen Gruppen. Kein Beleg für zwei Atemzüge, eine allgemeine Rangfolge oder bewiesene Ursachenmechanismen. Signifikante Schlaf-/HRV-Verbesserung wurde nicht nachgewiesen. Ob diese ODA-Pause dauerhaft gegen Angst hilft, wurde nicht untersucht."},{id:"C13",title:"Torre & Lieberman · 2018 · Forschungsüberblick zum Benennen von Gefühlen",url:"https://journals.sagepub.com/doi/abs/10.1177/1754073917742706",type:"research",finding:"Ein beschreibender Überblick betrachtet Zusammenhänge zwischen dem Benennen von Gefühlen und verschiedenen Emotionsmaßen. Benennen ist ein plausibler Versuch.",limitation:"Zusammenfassung und Quellenverzeichnis zugänglich. Keine bestätigte Gesamtteilnehmerzahl oder Wirksamkeitsschätzung. Ein Wort garantiert keine gefühlte Entlastung und löst keinen Stressauslöser. ODAs Kombination aus Situation und Gefühlswort ist eine Anpassung."},{id:"C14",title:"Kross et al. · 2014 · Selbstgespräche mit Abstand",url:"https://doi.org/10.1037/a0035173",type:"research",finding:"Sieben Studien umfassten 585 Teilnehmende. In einer strukturierten Begegnungsstudie verbesserte Nachdenken ohne Ich-Form die von Beobachtenden bewertete Leistung. Angst davor sank dabei nicht stärker als in der Vergleichsgruppe.",limitation:"Sozialer Stress im Labor, keine Behandlung von Angststörungen und kein Beweis sofortiger Ruhe. Genaue unabhängige Wiederholung und Vorabregistrierung wurden nicht bestätigt. ODAs zusätzlichen Arbeitsschritte wurden nicht untersucht."},{id:"C17",title:"Edwards & Loprinzi · 2018 · Studie zu kurzem Gehen und Meditation",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC6064756/",type:"research",finding:"66 junge Erwachsene wurden zufällig zehn Minuten Gehen auf dem Laufband, geführter Meditation oder stillem Sitzen zugeteilt. Wechselwirkungen bei Müdigkeit und Gesamtstimmung betrafen alle drei Gruppen. Die Stimmungsänderung innerhalb der Gehgruppe hatte p=0,10.",limitation:"Kleine Kurzzeitstudie ohne bestätigte Effekt-Konfidenzintervalle oder genaue unabhängige Wiederholung. Die Ergebnisse belegen weder eindeutig eine Gesamtstimmungsverbesserung durch Gehen noch Vorteile beliebiger zugänglicher Bewegungsalternativen."},{id:"C12",title:"Zaccaro et al. · 2018 · Forschungsüberblick zur Physiologie langsamen Atmens",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2018.00353/full",type:"research",finding:"Ein qualitativer Überblick über 15 Studien mit gesunden Personen fand Zusammenhänge zwischen langsamem Atmen und körperlichen sowie psychologischen Maßen. Es gab keine zusammengefasste Effektschätzung.",limitation:"Kleine, uneinheitliche Vorher-Nachher- oder innerpersonelle Studien, keine randomisierten Langzeitbefunde. Körperliche Zusammenhänge beweisen weder einen psychischen Wirkmechanismus über den Vagusnerv noch eine optimale Frequenz oder Behandlung von Angststörungen."},{id:"cyclic-sighing",title:"Balban et al. · 2023 · Studie zu strukturierten Atemübungen",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 Erwachsene wurden zufällig fünf täglichen Minuten Atemübung oder Achtsamkeit über 28 Tage zugeteilt. Die Atemgruppen zusammen verbesserten positive Gefühle durchschnittlich um 1,91 Punkte gegenüber 1,22; zyklisches Seufzen schnitt im Modell günstiger als Achtsamkeit ab. Angst besserte sich ohne signifikanten Gruppenunterschied.",limitation:"Kleine Gruppen, medizinische/psychiatrische Ausschlüsse, nachträgliche Registrierung und kein bestätigtes Konfidenzintervall zwischen Gruppen. Kein Beleg für zwei Atemzüge, eine allgemeine Rangfolge oder bewiesene Ursachenmechanismen. Signifikante Schlaf-/HRV-Verbesserung wurde nicht nachgewiesen. Ob diese ODA-Pause dauerhaft gegen Angst hilft, wurde nicht untersucht."},{id:"slow-breathing",title:"Zaccaro et al. · 2018 · Forschungsüberblick zur Physiologie langsamen Atmens",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2018.00353/full",type:"research",finding:"Ein qualitativer Überblick über 15 Studien mit gesunden Personen fand Zusammenhänge zwischen langsamem Atmen und körperlichen sowie psychologischen Maßen. Es gab keine zusammengefasste Effektschätzung.",limitation:"Kleine, uneinheitliche Vorher-Nachher- oder innerpersonelle Studien, keine randomisierten Langzeitbefunde. Körperliche Zusammenhänge beweisen weder einen psychischen Wirkmechanismus über den Vagusnerv noch eine optimale Frequenz oder Behandlung von Angststörungen."},{id:"activity-mood",title:"Singh et al. · 2023 · Überblick über Forschungsübersichten zu Bewegung",url:"https://www.newswise.com/pdf_docs/167719499939215_Singh%20et%20al%202023.pdf",type:"research",finding:"97 Übersichten umfassten 1.039 unterschiedliche Einzelstudien. Bei Depression lag die mediane SMD bei −0,43 (IQR −0,66 bis −0,27), bei Angst bei −0,42 (−0,66 bis −0,26). Belastung: SMD −0,60 (95%-Konfidenzintervall −0,78 bis −0,42) aus einer Übersicht mit sechs Studien.",limitation:"77 Übersichten hatten kritisch niedrige Qualität. Berichtete Teilnehmerzahlen überschneiden sich. Mediane und IQR sind keine zusammengefassten Effekte oder Konfidenzintervalle. Zusammenhänge in Intensitäts- und Dauerteilgruppen bestimmen keine persönliche Dosis und sagen nicht die Wirkung eines Spaziergangs voraus."},{id:"emotion-regulation",title:"Webb, Miles & Sheeran · 2012 · Meta-Analyse zur Emotionsregulation",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"306 experimentelle Vergleiche fanden im Durchschnitt Perspektivwechsel d+ 0,45, Neubewertung des Auslösers 0,36 und Gedankenunterdrückung −0,12.",limitation:"Nur die Zusammenfassung zugänglich; hauptsächlich kurzfristig erzeugte Gefühle im Labor. Gedanken- und Ausdrucksunterdrückung unterscheiden sich. Kein Beleg, dass Unterdrückung immer scheitert, eine tröstliche Deutung wahr ist oder ODA-Hinweise dauerhaft helfen."},{id:"affect-labeling",title:"Torre & Lieberman · 2018 · Forschungsüberblick zum Benennen von Gefühlen",url:"https://journals.sagepub.com/doi/abs/10.1177/1754073917742706",type:"research",finding:"Ein beschreibender Überblick betrachtet Zusammenhänge zwischen dem Benennen von Gefühlen und verschiedenen Emotionsmaßen. Benennen ist ein plausibler Versuch.",limitation:"Zusammenfassung und Quellenverzeichnis zugänglich. Keine bestätigte Gesamtteilnehmerzahl oder Wirksamkeitsschätzung. Ein Wort garantiert keine gefühlte Entlastung und löst keinen Stressauslöser. ODAs Kombination aus Situation und Gefühlswort ist eine Anpassung."},{id:"who-stress",title:"WHO · Stress: Fragen und Antworten",url:"https://www.who.int/news-room/questions-and-answers/item/stress",type:"guidance",finding:"Beschreibt Stress als Sorge oder innere Anspannung in schwierigen Situationen. Empfiehlt Alltagstruktur, Ruhe, passende Bewegung, vertraute Kontakte und einen bewussten Umgang mit Nachrichten.",limitation:"Allgemeine Empfehlungen, kein gemessener ODA-Effekt. Vorschläge müssen zur Person passen. Sie beseitigen nicht jeden Stressauslöser und ersetzen keine Versorgung."},{id:"nhs-stress",title:"NHS · Hilfe bei Stress",url:"https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/stress/",type:"guidance",finding:"Stress kann mit körperlichen, gedanklichen, emotionalen und verhaltensbezogenen Anzeichen einhergehen. Suche fachliche Unterstützung, wenn du schwer zurechtkommst oder Selbsthilfe nicht hilft.",limitation:"Anspannung, Kopfschmerzen oder Konzentrationsprobleme erklären ihre Ursache nicht. Neue oder beunruhigende Beschwerden können Abklärung brauchen. Benennen ist keine Diagnose."},{id:"nhs-stress-tips",title:"NHS · Zehn Anregungen gegen Stress",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/tips-to-reduce-stress/",type:"guidance",finding:"Passende Bewegung und vertraute Kontakte können beim Umgang mit Stress helfen. Weniger intensive Gefühle bedeuten nicht, dass die belastende Situation verschwunden ist.",limitation:"Empfehlungen ohne eigenständigen bezifferten Wirksamkeitsbeleg. Anderen zu helfen passt möglicherweise nicht bei Überlastung. Eine Kontaktliste ohne Bitte belegt keine erhaltene Unterstützung."},{id:"calm-nhs-anxiety",title:"NHS Every Mind Matters · Angst",url:"https://www.nhs.uk/every-mind-matters/mental-health-issues/anxiety/",type:"guidance",finding:"Empfiehlt, sich sicheren gefürchteten Situationen schrittweise zu stellen, Auslöser festzuhalten und bei beeinträchtigendem Alltag Hilfe zu suchen. Atemnot kann andere Ursachen haben.",limitation:"Allgemeine Empfehlungen erklären nicht jede gefürchtete Situation für sicher und bestätigen ODA nicht als Expositionsbehandlung. Gewalt oder echte Gefahr zu verlassen schützt dich."}],t=[{schemaVersion:2,revision:2,id:"calm-1",courseId:"calm",locale:"de",title:"Bevor du eine Antwort bereust: Halt kurz inne",goal:"Benenne einen vertrauten Stressmoment und wähle vor dem Antworten eine sichere, hilfreiche Handlung.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dein Kiefer ist angespannt, die Antwort fertig. Entscheide über den nächsten Schritt, bevor du auf Senden drückst.",reason:{id:"calm-1-reason",label:"Was kostet dich deine übliche Reaktion auf Stress?",kind:"text",maxLength:160,optional:!0,suggestions:["Antworten senden, die ich bereue","Prioritäten bleiben ungeklärt","Arbeitsanspannung mit nach Hause nehmen","Bisher keine solche Gelegenheit"]},why:{id:"calm-1-why",label:"Was würde dieser Schritt diese Woche schützen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Anspannung, Kopfschmerzen und Konzentrationsprobleme können Stress begleiten. Sie erklären aber nicht die Ursache. Nutze ein vertrautes Zeichen, um deine nächste Handlung zu wählen. Es ist keine Diagnose. Neue oder beunruhigende körperliche Beschwerden brauchen Abklärung.","Benenne Gefühl und Situation: „Sorge wegen dieser Frist.“ Benennen ist ein vernünftiger Versuch, keine Garantie für Entlastung. Tu dann etwas Hilfreiches: Verschiebe eine impulsive Antwort, frage nach der wichtigsten Aufgabe, setze eine sichere Grenze oder suche Unterstützung. Behalte dieses Startsignal und deine Handlung als Versuch durch den Kurs bei. Dich ruhiger zu fühlen ist kein nötiges Ergebnis."],example:{title:"Nora ändert ihre Antwort",text:"Nora sieht am Schreibtisch eine weitere Friständerung. Ihr vertrauter Kieferdruck taucht auf. Sie will scharf antworten. Sie benennt „Sorge wegen der Arbeitslast“ und fragt dann, welche Aufgabe Vorrang hat. Bis zum Mittagessen antwortet ihre Vorgesetzte nicht. Nora hält ihre Frage und die fehlende Antwort fest. Sie ist weiterhin besorgt."}},move:{invitation:"Behalte deine Handlung; passe das Fristbeispiel an.",instructions:["Benenne den Moment, ohne die Ursache zu diagnostizieren.","Nutze eine sichere Frage, Pause, Grenze oder Bitte um Unterstützung."],prompts:[],suggestions:{action:["Fragen, welche der beiden Fristen vorgeht","Eine impulsive Antwort aufschieben","Arbeitslast sachlich ohne scharfen Kommentar senden"],minimum:["Eine Frage zu beiden Fristen senden","Eine Antwort eine Minute ungesendet lassen","Einen sachlichen Satz zur Arbeitslast senden"],cue:["Wenn eine Mail eine Frist ändert","Wenn ich mein vertrautes Zeichen bemerke","Bevor ich eine scharfe Antwort sende"],place:["Am Schreibtisch, im Mailverlauf","Ein privater, sicherer Pausenort","Mein zugänglicher Ort zum Kommunizieren"],minutes:[2,1,5],fallback:["Entwurf ungesendet lassen; nur Prioritätsfrage schicken","Eine schützende Grenze wählen","Eine verfügbare Person um Unterstützung bitten"],observation:["Frage gesendet; Antwort oder keine Antwort","Ob der Impuls zum Senden wurde","Welches Zeichen und welche Handlung auftraten"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Fragen, welche der beiden Fristen vorgeht",minimum:"Eine Frage zu beiden Fristen senden",minutes:2,cueHint:"Wenn eine Mail eine Frist ändert",placeHint:"Am Schreibtisch, im Mailverlauf",obstacleHint:"Ich beginne, eine scharfe Antwort zu schreiben",fallbackHint:"Entwurf ungesendet lassen; nur Prioritätsfrage schicken",observationHint:"Frage gesendet; Antwort oder keine Antwort"},stopRule:"Neue oder beunruhigende Beschwerden brauchen Abklärung. Wähle Schutz oder Unterstützung, wenn die Situation unsicher ist.",accessibleAlternative:"Nutze äußere Hinweise, Tippen oder unterstützte Kommunikation. Für eine Bitte wähle „Diesen Schritt anpassen“ und „Unterstützung“ mit eigenem Minimum."},result:{question:"Hast du deine gewählte Handlung genutzt?",observationPrompt:"Was hast du nach dem Zeichen getan, und was folgte tatsächlich?"},judgment:{primary:{id:"calm-1-decision",scenario:"Nora erhält eine Friständerung. Die Situation ist sicher. Sie will aber scharf antworten, bevor sie die Prioritäten klärt.",question:"Welche Handlung nutzt das Zeichen sinnvoll?",options:[{id:"calm-1-full-explanation",text:"Sie erklärt die Arbeitslast sofort ausführlich und macht dann eine Pause, bevor sie die Antwort liest.",feedback:"Die Arbeitslast zu erklären kann helfen. Eine impulsive lange Nachricht verfehlt aber möglicherweise die Prioritätsfrage, die Nora klären muss. Sie kann zuerst eine klare Frage stellen, ohne die Frist für geklärt zu erklären."},{id:"calm-1-name-only",text:"Sie benennt ihre Sorge für sich und lässt die Arbeitslast gleich, bis sie darüber sprechen möchte.",feedback:"Benennen beschreibt den Moment, entscheidet aber keine Prioritäten und stellt keine Bitte. Nora darf weiter besorgt sein und trotzdem eine sichere Frage nutzen, die ihr tatsächliches Arbeitsproblem anspricht."},{id:"calm-1-priority-question",text:"Sie benennt die Fristsorge, hält die scharfe Antwort zurück und fragt, welche Aufgabe Vorrang hat.",feedback:"Das verbindet Bemerken mit einer hilfreichen Handlung. Die Vorgesetzte antwortet vielleicht nicht gleich. Nora hält deshalb ihre Frage fest und wählt eine Alternative, ohne Schweigen als Zustimmung zu werten."}],bestOptionId:"calm-1-priority-question"}},carry:{takeaway:"Benenne den Moment. Wähle dann eine Handlung, deren Ergebnis du beobachten kannst.",followUp:{questionId:"calm-1-return",question:"Führte das vertraute Zeichen zu deiner gewählten Handlung?",observationPrompt:"Was geschah, als dein gewähltes Startsignal auftauchte?",adjustmentPrompt:"Was solltest du wiederholen, ändern oder mit Unterstützung angehen?"}},goDeeper:{sections:[{heading:"Zeichen bemerken, ohne daraus eine Diagnose zu machen",paragraphs:["Die NHS-Empfehlungen nennen körperliche, gedankliche, emotionale und verhaltensbezogene Anzeichen, die Stress begleiten können [C02]. Ein vertrauter angespannter Kiefer, Gereiztheit oder verstreute Aufmerksamkeit können nützliche Hinweise sein. Diese Zeichen beweisen trotzdem nicht, dass Stress die Ursache ist. Sie können andere Erklärungen haben. Neue oder beunruhigende Beschwerden solltest du nicht als gewöhnliche Anspannung abtun. Einen vertrauten Moment zu benennen gibt dir Anlass zu wählen, stellt aber keine Diagnose.","Diese Lektion bittet dich um ein wiedererkennbares Startsignal. Du musst deinen Körper nicht nach Problemen absuchen. Nutze auch ein äußeres Ereignis wie das Öffnen einer schwierigen Mail. Lass die Augen offen und verwende deine übliche Kommunikation. Das Startsignal bietet eine Gelegenheit für eine sichere Frage, Pause, Grenze oder Bitte um Unterstützung. Das ist eine ODA-Anpassung zum Planen. Es zeigt weder ein stabiles Symptommuster bei jedem Menschen noch eine Gesundheitswirkung des Bemerkens allein."]},{heading:"Benennen ist noch nicht die ganze Handlung",paragraphs:["Torre und Liebermans beschreibender Forschungsüberblick betrachtet das Benennen von Gefühlen anhand verschiedener Emotionsmaße [C13]. Die zugängliche Zusammenfassung und das Quellenverzeichnis liefern keine Gesamtteilnehmerzahl oder bezifferte Wirksamkeitsschätzung. Gefühlt entlastet zu sein ist nicht garantiert. Ein Gefühlswort mit einer Situation zu verbinden ist eine ODA-Anpassung. Es ist keine genau wiederholte Behandlung und kein Verfahren, das dein Gehirn zurücksetzt.","Die NHS-Empfehlungen zum Prüfen von Gedanken helfen, eine Reaktion von der nächsten begründeten Entscheidung zu trennen [C10]. „Ich sorge mich wegen der Arbeitslast“ kann neben einem echten Arbeitslastproblem bestehen. Du brauchst vielleicht klarere Prioritäten, praktische Hilfe oder Schutz statt einer angenehmeren Geschichte. Der fortlaufende Versuch hält fest, was nach dem Startsignal passiert, auch eine unbeantwortete Frage. Spätere Lektionen bieten eine Hilfe nur dann an, wenn ein beobachtetes Hindernis sie passend macht. Du darfst sofort Unterstützung wählen. Dafür musst du nicht erst alle Werkzeuge beherrschen."]}],sourceIds:["C02","C13","C10"]}},{schemaVersion:2,revision:2,id:"calm-2",courseId:"calm",locale:"de",title:"Du musst dich nicht erst ruhig fühlen",goal:"Versuche eine angenehme Pause im Sitzen. Kehre dann zu deiner gewählten sicheren Handlung zurück.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Auf Ruhe zu warten kann das Gespräch erneut verschieben. Wähle eine angenehme Pause, nach der du handeln darfst.",reason:{id:"calm-2-reason",label:"Welche hilfreiche Handlung schiebst du auf, bis du dich bereit fühlst?",kind:"text",maxLength:160,optional:!0,suggestions:["Fragen, welche Frist vorgeht","Sagen, dass keine weitere Schicht geht","Hilfe bei der Pflegeorganisation anfragen","Ich schiebe keine Handlung auf"]},why:{id:"calm-2-why",label:"Was würde dieser Schritt diese Woche schützen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Eine Studie mit 108 Erwachsenen untersuchte fünf Minuten täglich über 28 Tage, keine zwei Atemzüge. Angst besserte sich in Atem- und Achtsamkeitsgruppen ohne statistisch signifikanten Unterschied zwischen ihnen. Das belegt keine schnelle Atemtechnik, die allen hilft.","Könnte eine Pause dir bei deiner gespeicherten Handlung helfen, setz dich sicher mit offenen Augen hin. Sanftes Atmen ohne Anstrengung ist optional. Du kannst auch bei normalem Atmen einen gewöhnlichen Gegenstand betrachten. Hör auf, wenn du dich unwohl fühlst. Wähle danach deinen sicheren nächsten Schritt. Du musst nicht ruhig sein, um anzufangen. Eine kürzere Pause übernimmt nicht den Studieneffekt."],example:{title:"Nora beendet die Übung",text:"Nora atmet zu Hause sanft im Sitzen, bevor sie nach der morgigen Arbeitslast fragt. Ihr wird benommen. Sie hört sofort auf, atmet normal und bleibt sitzen. Als es ihr gut geht, sendet sie die Prioritätsfrage. Stopp und Frage notiert sie getrennt. Die Pause war nicht angenehm genug zum Wiederholen. Nächstes Mal betrachtet sie einen Gegenstand."}},move:{invitation:"Behalte deine Handlung; passe das Fristbeispiel an.",instructions:["Sitze sicher. Wähle normales Atmen mit Fokus auf die Umgebung oder sanftes Atmen ohne Anstrengung.","Hör bei Unwohlsein auf. Nutze dann deine sichere Handlung, wenn es passt."],prompts:[],suggestions:{action:["Pausieren; fragen, welche Frist vorgeht","Gegenstand betrachten; fragen, welche Frist vorgeht","Prioritätsfrage ohne Pause senden"],minimum:["Eine Frage zu beiden Fristen senden","Einen klaren Satz zur Grenze senden","Fristpriorität ohne Atemübung erfragen"],cue:["Vor der Antwort auf eine Friständerung","Wenn eine Mail eine Frist ändert","Vor der Antwort zur Zusatzschicht"],place:["Gestützter Stuhl zu Hause, mit Handy","Am Schreibtisch, im Mailverlauf","Sitzplatz mit offenen Augen"],minutes:[2,1,5],fallback:["Pause beenden; Prioritätsfrage zur Frist senden","Atmen auslassen; Hilfe bei Arbeitslast anfragen","Aufhören; sitzen bleiben, bis Beschwerden nachlassen"],observation:["Pausenkomfort; Frage und Antwort oder Schweigen","Ob ich meine gewählte Handlung nutzte","Unwohlsein und tatsächliche Handlung"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Pausieren; fragen, welche Frist vorgeht",minimum:"Eine Frage zu beiden Fristen senden",minutes:2,cueHint:"Vor der Antwort auf eine Friständerung",placeHint:"Gestützter Stuhl zu Hause, mit Handy",obstacleHint:"Nach angenehmer Pause prüfe ich weiter meine Ruhe",fallbackHint:"Pause beenden; Prioritätsfrage zur Frist senden",observationHint:"Pausenkomfort; Frage und Antwort oder Schweigen"},stopRule:"Hör bei Schwindel oder Unwohlsein auf. Bleib sitzen, atme normal. Neue oder beunruhigende Beschwerden brauchen Abklärung; starke Brustschmerzen oder Atemnot brauchen dringende medizinische Hilfe.",accessibleAlternative:"Offene Augen und ein Fokus auf die Umgebung sind möglich. Kein Luftanhalten, erzwungenes Atmen oder Fahren mit Beschwerden."},result:{question:"Hast du deine gewählte Handlung sicher ausgeführt?",observationPrompt:"Welche Pause oder welcher Stopp fand statt, und kam danach deine nächste Handlung?"},judgment:{primary:{id:"calm-2-decision",scenario:"Nora wird beim Atmen zu Hause benommen. Sie möchte die Übung beenden, bevor sie ihre vorbereitete Frage sendet.",question:"Was passt zur Regel fürs Aufhören?",options:[{id:"calm-2-restart-later",text:"Sie wartet, bis das Gefühl vergeht, und beginnt die geplante Übung neu, bevor sie die Frage sendet.",feedback:"Neustarten macht die geplante Dauer trotz Beschwerden zur Pflicht. Nora sollte die Übung beenden, sicher normal atmen und Beschwerden abklären lassen. Sie muss sich die Erlaubnis zum Fragen nicht verdienen."},{id:"calm-2-stop-normal",text:"Sie hört auf, atmet sicher im Sitzen normal und sucht Abklärung, wenn Beschwerden anhalten oder beunruhigen.",feedback:"Sicherheit geht vor einer vollständigen Übung. Nora kann später einen Fokus auf die Umgebung wählen oder die Übung auslassen. Neue oder beunruhigende Beschwerden sollten nicht einfach für Stress gehalten werden."},{id:"calm-2-gentler-finish",text:"Sie verringert die Anstrengung, atmet sanfter bis zum Ende und entscheidet morgen über eine andere Methode.",feedback:"Sanfteres Atmen klingt nach Anpassung. Nach Benommenheit weiterzumachen widerspricht aber der Regel fürs Aufhören. Hör jetzt auf, bleib sicher sitzen und atme normal, statt die Übung fertigzumachen."}],bestOptionId:"calm-2-stop-normal"}},carry:{takeaway:"Eine hilfreiche Methode achtet deine Grenzen. Den nächsten Schritt entscheidest weiterhin du.",followUp:{questionId:"calm-2-return",question:"War die Pause angenehm, und unterstützte oder verzögerte sie deine gewählte Handlung?",observationPrompt:"Was geschah, als dein gewähltes Startsignal auftauchte?",adjustmentPrompt:"Was solltest du wiederholen, ändern oder mit Unterstützung angehen?"}},goDeeper:{sections:[{heading:"Die Studie belegt keinen schnellen Neustart des Körpers",paragraphs:["Balban und Kollegen teilten 108 Erwachsene zufällig kleinen Gruppen zu: fünf Minuten täglich über 28 Tage [C11]. Die Atemgruppen zusammen zeigten täglich durchschnittlich 1,91 Punkte mehr positive Gefühle gegenüber 1,22 bei Achtsamkeit. Zyklisches Seufzen schnitt in einem statistischen Modell günstiger als Achtsamkeit ab. Die zusammengefassten Rohmittelwerte sind kein Mittelwert nur für zyklisches Seufzen und beweisen keine allgemeine Rangfolge. Angst besserte sich ohne statistisch signifikanten Unterschied zwischen den Gruppen.","Die explorative Studie schloss bestimmte medizinische und psychiatrische Gruppen aus und wurde nachträglich registriert. Sie belegte keine statistisch signifikante Verbesserung von Schlaf oder Herzratenvariabilität. Auch ein Mechanismus über den Vagusnerv oder ein Nutzen von zwei Atemzügen wurde nicht bewiesen. Die Ergebnisse belegen nicht, dass diese kürzere Pause dauerhaft gegen Angst hilft. Diese Lektion bietet eine angenehme freiwillige Pause, statt das untersuchte doppelte Einatmen vorzuschreiben. Diese kürzere Anpassung wurde nicht auf Gleichwertigkeit mit dem Originalprotokoll geprüft."]},{heading:"Ob es angenehm ist, gehört zur Entscheidung",paragraphs:["Die NHS-Atemempfehlungen betonen eine bequem gestützte Haltung und sanftes Atmen ohne Anstrengung [C05]. Zählen ist optional; ein genaues Verhältnis von Ein- zu Ausatmen ist nicht nötig. Diese öffentlichen Hinweise sind praktische Empfehlungen, keine isoliert geprüfte Übungsdosis. Voller, schneller oder angestrengter zu atmen ist hier kein Ziel. Du darfst die Augen offen halten, normal atmen und einen vertrauten Gegenstand betrachten.","Die NHS-Panikinformation warnt, dass ähnliche körperliche Empfindungen bei anderen Erkrankungen vorkommen können [C04]. Hör bei Schwindel oder Unwohlsein auf. Bleib sicher sitzen und atme normal. Fahre nicht mit Beschwerden. Anhaltende oder beunruhigende Beschwerden brauchen Abklärung; schwere oder dringende Beschwerden brauchen örtliche Notfallhilfe. Wiederkehrende Panik oder Beeinträchtigung verdient ebenfalls fachliche Unterstützung. Dein Eintrag darf einen sicheren Stopp, eine unangenehme Übung und eine spätere Prioritätsfrage zeigen. Das sind unterschiedliche Tatsachen, kein misslungener Test, ruhig zu werden."]}],sourceIds:["C04","C05","C11"]}},{schemaVersion:2,revision:2,id:"calm-3",courseId:"calm",locale:"de",title:"Eine Pause braucht kein ganzes Training",goal:"Nutze passende kurze Bewegung nur, wenn sie deinem bisherigen Versuch mit Startsignal und Handlung im Alltag hilft.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Das ganze Training passt heute nicht. Hilft eine kleinere Pause vor der Handlung, die du noch erledigen willst?",reason:{id:"calm-3-reason",label:"Was kostete dich die letzte ausgelassene Pause? Keine kürzliche Gelegenheit zählt auch.",kind:"text",maxLength:160,optional:!0,suggestions:["Antworten weiter hastig geschickt","Anspannung in die nächste Aufgabe mitgenommen","Keine kürzlich ausgelassene Pause"]},why:{id:"calm-3-why",label:"Was würde dieser Schritt diese Woche schützen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bewegungsprogramme können Belastung im Durchschnitt verringern. Ihre Ergebnisse sagen aber nichts über einen einzelnen kurzen Spaziergang voraus. In einer kleinen Zehn-Minuten-Studie war die Gesamtstimmungsänderung durch Gehen statistisch nicht eindeutig. Eine hilfreiche Pause muss keine bessere Stimmung erzeugen, um als Versuch zu zählen.","Passt Bewegung vor deiner gespeicherten Handlung, versuche eine angenehme, zugängliche Form. Behalte das Startsignal und kehre danach zur Handlung zurück. Bewegung im Sitzen oder eine Pause ohne Bewegung können passen, übernehmen aber nicht den Effekt der Gehstudie. Halte gewählte Form und tatsächliche Dauer fest. Behalte deinen ursprünglichen Schritt, wenn er bereits funktioniert."],example:{title:"Nora bleibt bei der kleinen Variante",text:"Nora plante einen kurzen Spaziergang vor ihrer Prioritätsfrage am Nachmittag. Wegen Regen und einer Lieferung bleiben nur zwei Minuten. Sie bewegt sich stattdessen angenehm im Sitzen und sendet dann ihre vorbereitete Frage. Ihre Anspannung bleibt gleich. Sie notiert Variante, Dauer und gesendete Frage. Morgen kann sie das Passende wiederholen, ohne fehlende Minuten nachholen zu müssen."}},move:{invitation:"Behalte deine Handlung; passe das Sitzpausenbeispiel an.",instructions:["Füge Bewegung nur hinzu, wenn sie ein Hindernis deines gespeicherten Versuchs anspricht.","Für einen ersten Plan versuche eine Minute im Sitzen vor deiner vorbereiteten Prioritätsfrage.","Passt Bewegung nicht, ändere Handlung und Minimum auf die Frage allein."],prompts:[],suggestions:{action:["Im Sitzen bewegen; fragen, welche Frist vorgeht","Kurz gehen; die Prioritätsfrage senden","Prioritätsfrage ohne Bewegung senden"],minimum:["Eine Sitzminute; die Prioritätsfrage senden","Eine Gehminute; die Prioritätsfrage senden","Eine Frage zu beiden Fristen senden"],cue:["Nach dem Mittagessen, vor der Prioritätsfrage","Nach meiner üblichen Mittagspause","Wenn eine Mail eine Frist ändert"],place:["Gestützter Stuhl an meinem Schreibtisch","Mein gestützter Stuhl","Eine vertraute, sichere Gehstrecke"],minutes:[2,5,10],fallback:["Bewegung auslassen; Prioritätsfrage zur Frist senden","Handlung behalten; ungeeignete Bewegung auslassen","Nach passender Bewegungsanleitung fragen"],observation:["Tatsächliche Bewegungsminuten; Frage, Antwort oder Schweigen","Unwohlsein während der Pause","Unveränderte Gefühle zählen als Beobachtung"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Im Sitzen bewegen; fragen, welche Frist vorgeht",minimum:"Eine Sitzminute; die Prioritätsfrage senden",minutes:2,cueHint:"Nach dem Mittagessen, vor der Prioritätsfrage",placeHint:"Gestützter Stuhl an meinem Schreibtisch",obstacleHint:"Schmerz, Zugang oder Zeit verhindern passende Bewegung",fallbackHint:"Bewegung auslassen; Prioritätsfrage zur Frist senden",observationHint:"Tatsächliche Bewegungsminuten; Frage, Antwort oder Schweigen"},stopRule:"Beende Bewegung bei Schmerz, Schwindel oder Unwohlsein und suche passenden Rat. Nutze Bewegung nicht als Strafe.",accessibleAlternative:"Bewegung im Sitzen oder eine Pause ohne Bewegung sind möglich. Lässt du Bewegung aus, speichere die Frage allein als Handlung und Minimum."},result:{question:"Hast du deine gewählte Pause und Handlung genutzt?",observationPrompt:"Welche Variante und Dauer gab es, und was hast du danach getan?"},judgment:{primary:{id:"calm-3-decision",scenario:"Nora bemerkt hastige Antworten nach ausgelassenen Pausen. Sie hat zwei Minuten, eine vorbereitete Prioritätsfrage und passende Sitzbewegungen. Regen verhindert ihren Spaziergang.",question:"Welcher Plan testet ihr beobachtetes Hastproblem am besten?",options:[{id:"calm-3-larger-tomorrow",text:"Sie sendet die Frage jetzt und plant den Spaziergang für eine spätere Pause mit besserem Wetter.",feedback:"Jetzt zu senden klärt Prioritäten zügig. Ein späterer Spaziergang bleibt möglich. Ihre beobachtete Hast bleibt damit aber ungeprüft. Eine passende Minute Bewegung wäre vor der vorbereiteten Frage noch möglich."},{id:"calm-3-research-first",text:"Sie vergleicht zwei Minuten Bewegungsabläufe und wählt eine Strecke, bevor sie nach Prioritäten fragt.",feedback:"Recherche kann helfen, wenn eine passende Möglichkeit fehlt. Nora hat hier schon eine. Weiteres Vergleichen ersetzt Pause und Frage durch Vorbereitung, die das heutige Hindernis nicht löst."},{id:"calm-3-suitable-small",text:"Sie nutzt ihre passende Sitzminute, sendet die vorbereitete Frage und notiert die Variante, ohne Entlastung zu verlangen.",feedback:"Das passt zur verfügbaren Zeit und erhält die hilfreiche Handlung. Bewegung im Sitzen ist eine Anpassung, nicht das untersuchte Gehprotokoll. Unveränderte Anspannung ist eine ehrliche Beobachtung."}],bestOptionId:"calm-3-suitable-small"}},carry:{takeaway:"Nutze die Variante, die passt. Mach eine ausgelassene Pause nicht zu einer Schuld für morgen.",followUp:{questionId:"calm-3-return",question:"Passte die Pause zu deinem Körper, und blieb Zeit für die gewählte Handlung?",observationPrompt:"Was geschah, als dein gewähltes Startsignal auftauchte?",adjustmentPrompt:"Was solltest du wiederholen, ändern oder mit Unterstützung angehen?"}},goDeeper:{sections:[{heading:"Programmdurchschnitte sagen keine einzelne Pause voraus",paragraphs:["Singh und Kollegen fassten 97 Übersichten mit 1.039 unterschiedlichen randomisierten Einzelstudien zusammen [C07]. Die Ergebnisse zu Depression und Angst waren mediane standardisierte Effekte über Übersichten hinweg. Es war keine einzelne zusammengefasste Schätzung aus individuellen Teilnehmerdaten. Depression lag bei −0,43 mit einem Interquartilsabstand von −0,66 bis −0,27; Angst bei −0,42 mit −0,66 bis −0,26. Diese Bereiche sind keine Konfidenzintervalle. Die von den Übersichten berichteten Teilnehmerzahlen enthalten Überschneidungen.","Die Belastungsschätzung von −0,60 mit einem 95%-Konfidenzintervall von −0,78 bis −0,42 stammte aus einer Übersicht mit sechs Studien. 77 Übersichten wurden als kritisch niedrig in ihrer Qualität bewertet. Zusammenhänge mit Intensität oder Programmdauer zeigen nicht, dass härter oder kürzer für einen bestimmten Menschen besser ist. Die breite Studienbasis spricht dafür, passende Bewegung neben anderer Unterstützung zu erwägen. Sie rechtfertigt weder eine Steigerung deiner zweiminütigen Pause noch das Versprechen, dass deine heutige Anspannung sinkt."]},{heading:"Was ein kurzer Gehversuch dir zeigen kann",paragraphs:["Edwards und Loprinzi teilten 66 junge Erwachsene zufällig zehn Minuten Gehen auf dem Laufband, geführter Meditation oder stillem Sitzen zu [C17]. Die Wechselwirkungen bei Müdigkeit und Gesamtstimmung verglichen alle drei Gruppen. Es waren keine Effektschätzungen nur für Gehen. Die Gesamtstimmungsänderung innerhalb der Gehgruppe hatte p=0,10. Die genauen Ergebnisse belegen deshalb keinen eindeutigen Gesamtstimmungsnutzen dieses Spaziergangs. Effekt-Konfidenzintervalle und eine genaue unabhängige Wiederholung wurden nicht bestätigt.","Eine Innenstrecke, angenehmes Tempo, Sitzbewegung oder Pause ohne Bewegung ist eine ODA-Anpassung, nicht dieses Laborverfahren. NHS-Empfehlungen nennen Bewegung als eine Bewältigungsmöglichkeit. Sie beseitigt aber nicht den Stressauslöser [C06]. Nutze deine Einträge, um Passung, Zugang und deine geplante nächste Handlung zu prüfen. Eine Gefühlsänderung vorher und nachher beweist keine Ursache. Eine Erkrankung, Schmerzen oder Sorgen ums Essen können qualifizierten Rat brauchen, statt eines größeren Bewegungsziels."]}],sourceIds:["C06","C07","C17"]}},{schemaVersion:2,revision:2,id:"calm-4",courseId:"calm",locale:"de",title:"„Können wir reden?“ Prüfe deine Deutung",goal:"Trenne Beobachtung von Vorhersage. Nutze dann eine sichere, praktische Handlung.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Eine vage Nachricht, und du erwartest schon das Schlimmste. Prüfe vor deinem nächsten Schritt, was du weißt.",reason:{id:"calm-4-reason",label:"Was schiebst du auf, weil deine Vorhersage schon sicher wirkt?",kind:"text",maxLength:160,optional:!0,suggestions:["Fragen, was ich vorbereiten soll","Eine mögliche Korrektur senden","Hilfe bei einer unsicheren Situation anfragen","Ich schiebe keine Handlung auf"]},why:{id:"calm-4-why",label:"Was würde dieser Schritt diese Woche schützen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein ausgewogener Gedanke ist nicht unbedingt positiv. Die NHS-Empfehlungen bitten dich, Belege zu prüfen und umfassender hinzusehen. „Ich weiß es noch nicht“ kann genauer sein als „Ich habe Ärger“ oder „Sie schätzen mich bestimmt“. Keines dieser ausgedachten Motive ist eine Tatsache.","Kehre zum selben Startsignal und derselben Handlung zurück. Blockierte eine Vorhersage den Schritt, benenne, was gesagt oder getan wurde. Wähle dann sichere Klärung, Korrektur, eine Grenze oder Unterstützung. Anders zu denken beseitigt keine echte Überlastung oder schlechte Behandlung. Teste die Handlung und die folgenden Belege, auch wenn Unsicherheit bleibt."],example:{title:"Nora fragt, was sie vorbereiten soll",text:"Nora erhält „Können wir morgen reden?“ und erwartet, dass sie ein Problem verursacht hat. Sie notiert die tatsächliche Nachricht und fragt, was sie für die sichere Besprechung vorbereiten soll. Ihre Vorgesetzte antwortet: „Den geänderten Kundenzeitplan.“ Das gibt Nora eine sinnvolle Aufgabe, keine Gewissheit über das ganze Gespräch. Sie bereitet den Zeitplan vor und notiert den Austausch. Nervös bleibt sie trotzdem."}},move:{invitation:"Behalte deine Handlung; passe das Beispiel zur Vorbereitungsfrage an.",instructions:["Trenne deine Beobachtung von deiner Vorhersage.","Frage, korrigiere, schütze dich oder suche Unterstützung. Erfinde kein fremdes Motiv."],prompts:[],suggestions:{action:["Fragen, was fürs Treffen vorbereitet werden soll","Eine unklare Anfrage klären","Eine sichere Korrektur oder Grenze umsetzen"],minimum:["Eine Vorbereitungsfrage senden","Eine Klärungsfrage stellen","Einen gewählten Schutzschritt machen"],cue:["Wenn eine Nachricht kein Gesprächsthema nennt","Wenn eine schwierige Arbeitsmail kommt","Bevor ich nach einer Vorhersage handle"],place:["Am Schreibtisch, in der Mail meiner Vorgesetzten","Ein privater Ort für unterstützte Kommunikation","Mein zugänglicher Ort für Notizen und Kontakt"],minutes:[2,1,5],fallback:["Aktuellen Zeitplan mitbringen; beim Treffen fragen","Schutz oder Unterstützung wählen","Eine sicherere Gelegenheit zum Klären abwarten"],observation:["Frage gesendet; Thema erfahren oder noch unbekannt","Erfahrene Fakten, auch bleibende Unsicherheit","Welchen sicheren Schritt ich tatsächlich machte"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Fragen, was fürs Treffen vorbereitet werden soll",minimum:"Eine Vorbereitungsfrage senden",minutes:2,cueHint:"Wenn eine Nachricht kein Gesprächsthema nennt",placeHint:"Am Schreibtisch, in der Mail meiner Vorgesetzten",obstacleHint:"Nachfragen ist sicher, aber die Vorgesetzte kann vorab nicht antworten",fallbackHint:"Aktuellen Zeitplan mitbringen; beim Treffen fragen",observationHint:"Frage gesendet; Thema erfahren oder noch unbekannt"},stopRule:"Deute schlechte Behandlung nicht in Akzeptanz um. Nutze bei Bedarf Sicherheit, Grenzen oder Unterstützung.",accessibleAlternative:"Nutze Schreiben, unterstützte Kommunikation oder eine vertraute Hilfsperson. Körperbeobachtung ist nicht nötig."},result:{question:"Hast du deinen gewählten, auf Fakten gestützten Schritt getan?",observationPrompt:"Was hast du gefragt oder getan, und welche Belege folgten tatsächlich?"},judgment:{primary:{id:"calm-4-decision",scenario:"Nora bekommt „Können wir morgen reden?“. Eine Rückfrage bei ihrer Vorgesetzten ist sicher möglich und könnte heute beantwortet werden. Nora hat zehn Minuten und die aktuelle Arbeit, kennt aber kein Thema.",question:"Welche Handlung prüft die Vorhersage?",options:[{id:"calm-4-positive-story",text:"Sie sammelt Gründe, warum ihre Vorgesetzte ihre Arbeit schätzen könnte, und bereitet sich auf ein positives Gespräch vor.",feedback:"Eine positive Erklärung ist möglich, bleibt aber ein geratenes Motiv. Nora kann das Ergebnis offenlassen und nach der Vorbereitung fragen, statt eine beruhigende Geschichte für sicher zu halten."},{id:"calm-4-clarify",text:"Sie notiert die genaue Nachricht, fragt nach der Vorbereitung und wählt anhand der Antwort einen praktischen Schritt.",feedback:"Das trennt bekannte Fakten von Vorhersagen und sammelt passende Informationen. Die Antwort kann Unsicherheit lassen. Nora gewinnt trotzdem eine klarere Handlung, ohne sich beruhigt fühlen oder ein Motiv annehmen zu müssen."},{id:"calm-4-review-everything",text:"Sie prüft die aktuelle Arbeit zehn Minuten und bringt sie morgen mit, ohne nach dem Thema zu fragen.",feedback:"Begrenztes Prüfen kann die Arbeit verbessern. Hier könnte es aber das falsche Material vorbereiten: Das Thema fehlt, und die Vorgesetzte kann jetzt klären. Sorge belegt keinen Fehler."}],bestOptionId:"calm-4-clarify"}},carry:{takeaway:"Ein umfassender Blick darf sagen „Ich weiß es noch nicht“ und trotzdem eine hilfreiche Handlung wählen.",followUp:{questionId:"calm-4-return",question:"Brachte die Handlung Belege, oder hast du eine Vermutung durch eine andere ersetzt?",observationPrompt:"Was geschah, als dein gewähltes Startsignal auftauchte?",adjustmentPrompt:"Was solltest du wiederholen, ändern oder mit Unterstützung angehen?"}},goDeeper:{sections:[{heading:"Ausgewogenheit verlangt keine angenehmere Gewissheit",paragraphs:["Die NHS-Empfehlungen zum Umdeuten nennen Bemerken, Belege prüfen und eine ausgewogene Alternative erwägen [C10]. Eine tatsächliche Beobachtung wäre: „Die Nachricht bittet um ein Gespräch morgen.“ Eine Vorhersage wäre: „Ich verliere meine Stelle.“ Eine Möglichkeit wäre: „Vielleicht gibt es ein Zeitplanproblem.“ Sie bleibt eine Möglichkeit, bis Belege eintreffen. Du musst nicht die beste Erklärung glauben, um eine sichere, praktische Frage zu stellen.","Fakt und Vorhersage zu trennen und dann nachzufragen ist eine ODA-Anpassung, keine bestätigte eigenständige kognitive Verhaltenstherapie. Ein bekannter Fehler kann Korrektur verlangen. Eine dokumentierte unangemessene Forderung kann Verhandeln oder Unterstützung verlangen. Gewalt und Zwang brauchen Schutz, keine großzügigere Deutung der anderen Person. NHS-Angstempfehlungen unterscheiden das schrittweise Arbeiten mit sicheren gefürchteten Situationen von nötiger Versorgung bei beeinträchtigendem Alltag [C03]. Diese Lektion ist keine Expositionstherapie."]},{heading:"Andere Gefühle liefern keine anderen äußeren Belege",paragraphs:["Webb und Kollegen fassten 306 experimentelle Vergleiche zusammen [C09]. Perspektivwechsel und Neubewertung des Auslösers beeinflussten Gefühle im Durchschnitt, überwiegend in kurzen Laboraufgaben. Die zusammengefasste Schätzung für Gedankenunterdrückung lag bei −0,12. Das zeigt nicht, dass jeder Versuch, einen Gedanken beiseitezulegen, scheitert. Auch den Gefühlsausdruck zu unterdrücken ist etwas anderes. Weniger Angst zu spüren belegt ebenso wenig, dass eine neue Deutung wahr ist.","Die geöffnete Zusammenfassung lieferte keine Konfidenzintervalle und bestätigte keine Gesamtteilnehmerzahl. Langfristige Effekte dieses kurzen ODA-Arbeitsblatts bleiben ungeprüft. Praktisch geht es darum, eine Vorhersage nicht schon als Beobachtung zu behandeln. Wähle dann eine sichere Handlung, die zu deinem fortlaufenden Versuch passt. Halte Handlung und tatsächliches Ergebnis gemeinsam fest. Eine Frage ohne Antwort lässt Unsicherheit bestehen. Auch das ist gültige Information für den nächsten Versuch oder eine Entscheidung für Unterstützung."]}],sourceIds:["C03","C09","C10"]}},{schemaVersion:2,revision:2,id:"calm-5",courseId:"calm",locale:"de",title:"Trag diese Woche nicht länger allein",goal:"Prüfe denselben Versuch. Wiederhole eine hilfreiche Handlung oder bitte konkret um nötige Unterstützung.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Trägst du die Woche noch allein? Wähle anhand deiner Einträge den nächsten Schritt oder bitte um echte Unterstützung.",reason:{id:"calm-5-reason",label:"Wobei brauchst du Hilfe statt einer weiteren Technik?",kind:"text",maxLength:160,optional:!0,suggestions:["Einen Versorgungstermin organisieren","Termine trotz gestörtem Schlaf bewältigen","Eine Arbeitslast, die ich allein nicht schaffe"]},why:{id:"calm-5-why",label:"Was würde dieser Schritt diese Woche schützen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Fachliche Unterstützung passt, wenn du schwer zurechtkommst oder Selbsthilfe nicht hilft. Du brauchst weder eine Krise noch eine perfekte Erklärung oder einen fertigen Kurs. Eine Unterstützungsliste ist Vorbereitung. Konkret um Hilfe zu bitten ist der Kontaktversuch.","Prüfe deine Einträge zum Versuch mit Startsignal und Handlung. Behalte eine machbare Handlung oder bitte um Hilfe. Hast du noch nichts versucht, wähle eine erste sichere Gelegenheit. „Hilfst du mir, einen Termin zu vereinbaren?“ ist konkret. Keine Antwort zählt trotzdem als Kontaktversuch. Wiederkehrende Panik oder Alltagsbeeinträchtigung braucht Abklärung. Unterstützung muss nicht auf Übung warten."],example:{title:"Nora bittet um Hilfe bei ihrer Belastung",text:"Noras Einträge zeigen drei klare Prioritätsfragen. Trotzdem schläft sie schlecht und schafft Versorgungstermine kaum. Sie fragt ihre Schwester: „Hilfst du mir, heute in der Praxis anzurufen?“ Sie bittet auch um Abklärung. Die Schwester kann erst morgen helfen. Nora notiert beide Kontakte und behält eine Arbeitslastfrage für nächste Woche bei, ohne eine weitere Übung hinzuzufügen."}},move:{invitation:"Behalte deinen Plan; passe das Beispiel zum Praxiskontakt an.",instructions:["Prüfe Einträge. Wiederhole das Passende oder bitte um nötige Unterstützung.","Benenne vor dem Speichern Empfänger, Bitte, verfügbare Gelegenheit und einen Ersatzkontakt."],prompts:[],suggestions:{action:["Die Terminvergabe der Hausarztpraxis anrufen","Schwester um Hilfe bei Terminvereinbarung bitten","Freund um zehn gemeinsame Minuten bitten"],minimum:["Abklärung zu Schlaf- und Terminproblemen anfragen","Schwester eine Bitte zur Terminunterstützung senden","Eine Bitte um zehn Gesprächsminuten senden"],cue:["Nach dem Mittagessen während der Telefonzeiten","Heute nach dem Mittagessen","Wenn die Terminvergabe der Hausarztpraxis öffnet"],place:["Zu Hause mit meinem Handy","Am Küchentisch mit zugänglichem Nachrichtenzugang","Privater Raum mit zugänglichen Kontaktmitteln"],minutes:[2,5,10],fallback:["Das zugängliche Terminanfrageformular der Hausarztpraxis nutzen","Schwester um Hilfe beim Hausarztpraxiskontakt bitten","Die Hausarztpraxis zur nächsten Öffnung anrufen"],observation:["Kontakt versucht; Antwort und nächster Zugangsschritt","Ob praktische Unterstützung stattfand","Nächster Zugangsschritt, auch ohne Antwort"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Die Terminvergabe der Hausarztpraxis anrufen",minimum:"Abklärung zu Schlaf- und Terminproblemen anfragen",minutes:2,cueHint:"Nach dem Mittagessen während der Telefonzeiten",placeHint:"Zu Hause mit meinem Handy",obstacleHint:"Die Terminvergabe der Hausarztpraxis antwortet nicht",fallbackHint:"Das zugängliche Terminanfrageformular der Hausarztpraxis nutzen",observationHint:"Kontakt versucht; Antwort und nächster Zugangsschritt",kind:"support"},stopRule:"Gedanken an Selbstverletzung brauchen umgehende fachliche Hilfe oder Krisenhilfe. Kannst du deine Sicherheit nicht gewährleisten oder bist unmittelbar in Gefahr, nutze örtliche Notfallhilfe.",accessibleAlternative:"Wähle „Diesen Schritt anpassen“, dann „Unterstützung“ für einen Kontaktplan. Öffentliche Anlaufstellen, unterstützter Kontakt, Nachrichten oder Telefon sind möglich. Benenne vor dem Speichern Empfänger, Bitte, Gelegenheit und verfügbare Alternative."},result:{question:"Hast du deine gewählte Bitte oder Handlung ausgeführt?",observationPrompt:"Was hast du gefragt oder getan, und welche Unterstützung folgte tatsächlich?"},judgment:{primary:{id:"calm-5-decision",scenario:"Noras Angst stört wiederholt Schlaf und Termine. Sie kann ihre Sicherheit gewährleisten. Die Terminvergabe ihrer Hausarztpraxis ist jetzt offen und zugänglich. Eine Beratungsstelle vermittelt Kontakte. Ihre Schwester kann morgen helfen.",question:"Welcher nächste Plan passt zu ihren Einträgen?",options:[{id:"calm-5-support-and-care",text:"Sie kontaktiert die Hausarztpraxis heute mit einer kurzen Beschreibung der Folgen und bittet dann um nötige praktische Hilfe.",feedback:"Das nutzt einen zugänglichen Weg zur Abklärung, ohne auf Krise oder perfekte Gewissheit zu warten. Ihre Schwester kann später helfen. Ändert sich die unmittelbare Sicherheit, ist der dringende Weg nötig."},{id:"calm-5-friends-first",text:"Sie bittet ihre Schwester, morgen einen Termin mit ihr zu vereinbaren, und notiert die Folgen im Alltag.",feedback:"Gemeinsames Vereinbaren kann Zugang erleichtern. Hier erreicht Nora ihre bekannte Hausarztpraxis aber selbst schon heute. Auf morgige Hilfe zu warten verzögert verfügbare Abklärung. Ihre Schwester kann später trotzdem helfen."},{id:"calm-5-complete-explanation",text:"Sie ruft heute die öffentliche Beratungsstelle an, sucht eine Fachperson und entscheidet dann, welche Terminvergabe sie kontaktiert.",feedback:"Vermittlung hilft, wenn eine zugängliche Fachperson fehlt. Noras Hausarztpraxis ist jetzt erreichbar. Weiterzusuchen fügt einen Schritt hinzu, ohne ihren aktuellen Zugangsbedarf zu klären. Beide Wege bleiben berechtigte Möglichkeiten."}],bestOptionId:"calm-5-support-and-care"}},carry:{takeaway:"Behalte, was passte. Bitte um die Hilfe, die das verbleibende Problem tatsächlich braucht.",followUp:{questionId:"calm-5-return",question:"Was geschah bei deiner Bitte oder Handlung, und welche Antwort oder welcher Zugangsschritt steht noch aus?",observationPrompt:"Was geschah, als dein gewähltes Startsignal auftauchte?",adjustmentPrompt:"Was solltest du wiederholen, ändern oder mit Unterstützung angehen?"}},goDeeper:{sections:[{heading:"Eine Bitte braucht Empfänger und konkreten Inhalt",paragraphs:["WHO- und NHS-Empfehlungen nennen vertraute Kontakte und praktische Möglichkeiten, mit Belastung umzugehen [C01, C02]. Dieser Kurs macht daraus eine optionale konkrete Bitte: um ein Gespräch, Hilfe bei einer Aufgabe oder Unterstützung beim Kontakt zur Versorgung. Wortlaut und Ersatzweg sind ODA-Entscheidungen, keine bestätigte isolierte Intervention. Eine gesendete Bitte ist eine beobachtbare Handlung. Unterstützung zu erhalten, sich besser zu fühlen und den Stressauslöser zu lösen sind getrennte Ergebnisse.","Prüfe Pläne und Versuche deines Experiments, statt eine weitere Routine zu sammeln. Welche Handlung war nutzbar? Was störte? Was übersteigt noch deine Kraft? Ein unversuchter Plan hat kein bekanntes Ergebnis. Wähle eine erste sichere Gelegenheit oder nötige Unterstützung. Jemand kann fehlen oder ablehnen. Das gibt dir Information für einen anderen Kontakt oder eine öffentliche Anlaufstelle. Du brauchst kein vertrautes persönliches Netzwerk, um fachliche Hilfe zu erbitten. Behalte sensible Details für dich, wenn du möchtest, und wähle trotzdem einen konkreten nächsten Schritt zum Zugang."]},{heading:"Abklärung darf vor einem Notfall beginnen",paragraphs:["Die NHS-Stressempfehlungen raten zu fachlicher Unterstützung, wenn Zurechtkommen schwierig ist oder Selbsthilfe nicht hilft [C02]. Wiederkehrende Panik braucht Abklärung: Beschwerden können andere Ursachen haben, und Behandlungsentscheidungen brauchen möglicherweise klinische Unterstützung [C04]. Neue körperliche Beschwerden solltest du nicht automatisch Stress nennen. Dieser Kurs empfiehlt weder Medikamentenänderungen noch eine feste Zahl von Verhaltenstherapiesitzungen oder ein Behandlungspaket aus Schlaf, Bewegung und Atmen.","Gedanken an Selbstverletzung brauchen auch ohne unmittelbare Gefahr umgehende fachliche Hilfe oder Krisenhilfe. Kannst du deine Sicherheit nicht gewährleisten oder bist unmittelbar in Gefahr, nutze jetzt örtliche Notfallhilfe. Bitte eine vertraute Person zu bleiben, wenn das sicher ist. Das sind Sicherheitswege, keine Diagnose und kein bestätigtes Verfahren zur Dringlichkeitseinstufung. Der letzte Lernschritt darf eine passende Handlung beibehalten, Ruhe wählen, den Versuch pausieren oder Versorgung anfragen. Für keine dieser Entscheidungen musst du erst eine ganze Reihe von Techniken abschließen."]}],sourceIds:["C01","C02","C04"]}}],r=[{practice:["Bemerke ein vertrautes Körpersignal oder äußeres Ereignis. Ein körperliches Symptom erklärt seine Ursache nicht.","Gib dem Gefühl einen Namen in einem Wort. Es muss nicht das perfekte Wort sein.","Beschreibe die Situation dahinter in einem Satz: „In dieser Situation fühle ich mich …“"],reflection:"An welchem Zeichen bemerkst du Stress am häufigsten?",question:"Welche Sicht auf Stress passt zu dieser Lektion?",options:["Wenn ich Stress habe, muss etwas sehr falsch sein. Ich muss ihn sofort loswerden.","Stress ist eine gewöhnliche Reaktion auf schwierige Situationen. Bemerken und Benennen können ein erster Schritt sein.","Mein Gefühl zu benennen macht es nur größer. Deshalb sollte ich es ignorieren."],correct:1,feedback:"Stress kann schwierige Situationen begleiten. Bemerken und Benennen können bei einer hilfreichen Handlung helfen, garantieren aber keine Entlastung. Neue Beschwerden oder Schwierigkeiten beim Zurechtkommen können Abklärung oder Unterstützung brauchen."},{practice:["Wenn es passt, sitze sicher und versuche die untersuchte Fünf-Minuten-Routine freiwillig. Normales Atmen und ein Fokus auf die Umgebung sind Alternativen.","Atme beim zyklischen Seufzen langsam ein, dann kürzer nach, ohne Fülle zu erzwingen. Atme langsam aus. Hör bei Schwindel oder Unwohlsein auf.","Notiere Wohlbefinden, tatsächliche Übung oder Stopp getrennt von Stimmung. Neue oder beunruhigende Beschwerden brauchen Abklärung. Fahre nicht mit Beschwerden."],reflection:"Was hast du im Körper bemerkt, als du länger ausgeatmet hast?",question:"Worauf liegt der Schwerpunkt beim zyklischen Seufzen?",options:["Die Luft möglichst lange anhalten.","Schnelle, tiefe Atemzüge hintereinander machen.","Langsam und lange ausatmen."],correct:2,feedback:"Zyklisches Seufzen nutzt zweimal Einatmen und langsames Ausatmen. Untersucht wurden fünf Minuten täglich über 28 Tage, kein schneller Neustart. Hör bei Schwindel oder Unwohlsein auf und atme wieder normal."},{practice:["Wähle heute passende Bewegung, auch eine zugängliche Sitzvariante. Passt Bewegung nicht, behalte eine Pause ohne Bewegung.","Verbinde sie mit einem ohnehin vorhandenen Tagesmoment, etwa einem kurzen Spaziergang nach dem Mittagessen.","Wenn hilfreich, notiere Anspannung vor und nach Bewegung. Unveränderte Gefühle sind gültig. Eine Änderung beweist keine Ursache."],reflection:"Welche Bewegung fühlt sich für dich wie eine Pause an statt wie eine Strafe?",question:"Wie sollten wir den Überblick von Singh und Kollegen aus dem Jahr 2023 lesen?",options:["Bewegung hängt mit weniger Symptomen zusammen. Die meisten Übersichten hatten aber niedrige Qualität.","Wer sich bewegt, verliert sicher seine Angst.","Wenn ich mich bewege, brauche ich keine Medikamente oder Therapie mehr."],correct:0,feedback:"Bewegungsprogramme verringerten Symptome im Durchschnitt. Die meisten enthaltenen Übersichten hatten aber kritisch niedrige Qualität. Ihre medianen Ergebnisse sagen keine einzelne kurze Pause voraus und ersetzen keine nötige Versorgung."},{practice:["Schreibe in einem Satz eine Situation auf, die dich zuletzt belastet hat.","Erwäge plausible Alternativen, ohne Motive zu erfinden. Eine unsichere Erklärung kann genauer sein als eine positive.","Stell dir vor, wie eine neutrale Person die Situation sehen würde. Sag dir dann, was du einem Freund in derselben Lage sagen würdest."],reflection:"Was änderte sich durch den anderen Blickwinkel auf die Situation, und was blieb gleich?",question:"Welche Strategie schnitt in der Meta-Analyse von Webb und Kollegen aus dem Jahr 2012 besser ab?",options:["Versuchen, überhaupt nicht an das Ereignis zu denken.","Versuchen, die Situation mit den Augen einer außenstehenden Person zu sehen.","Am negativen Gefühl festhalten und immer weiter darüber grübeln."],correct:1,feedback:"Perspektivwechsel und Neubewertung beeinflussten kurze Laborgefühle im Durchschnitt. Die zusammengefasste Schätzung zur Gedankenunterdrückung war negativ. Das beweist nicht, dass Unterdrückung immer scheitert. Nutze Belege und eine sichere nächste Handlung."},{practice:["Benenne verfügbare vertraute Kontakte oder öffentliche Anlaufstellen. Ein persönliches Netzwerk ist keine Voraussetzung, um Versorgung anzufragen.","Wähle diese Woche einen Moment, um jemandem zu sagen, wie es dir geht, oder um etwas Unterstützung zu bitten.","Notiere anhand der Hilfetabelle für dich, an wen du dich in welcher Situation wenden wirst."],reflection:"Wen würdest du an einem schweren Tag als Erstes erreichen wollen?",question:"Was solltest du tun, wenn du deine Sicherheit nicht gewährleisten kannst oder unmittelbar in Gefahr bist?",options:["Erst die übrigen Kursübungen abschließen und abwarten.","Es allein bewältigen, damit ich niemanden belaste.","Die örtliche Notrufnummer anrufen und wenn möglich jemanden bitten, bei mir zu bleiben."],correct:2,feedback:"Nutze örtliche Notfallhilfe, wenn du deine Sicherheit nicht gewährleisten kannst oder unmittelbar in Gefahr bist. Gedanken an Selbstverletzung brauchen auch ohne unmittelbare Gefahr umgehende fachliche Hilfe oder Krisenhilfe. Warte nicht auf den Kursabschluss."}],s=[{id:"1758876019128-e76eebf402bd",alt:"Müde Person stützt am Tisch den Kopf auf eine Hand"},{id:"1717691526463-975c4119505c",alt:"Frau steht mit geschlossenen Augen vor einem Baum"},{id:"1758272421829-7028296dee8f",alt:"Frau dehnt sich auf dem Wohnzimmerboden"},{id:"1658279366796-e0c28623cd27",alt:"Frau sitzt auf einem Fensterbrett und schaut hinaus"},{id:"1747764925585-6c2df83b3fd2",alt:"Zwei Frauen unterhalten sich beim Kaffee"}],a={lang:"de",id:"calm",title:"Stress tippt deine Antworten? Entscheide den nächsten Schritt selbst",subtitle:"Fünf Lektionen: ein Stresszeichen bemerken, eine sichere Handlung versuchen und einen sinnvollen nächsten Schritt wählen, während Gefühle sich verändern.",description:"Gestalte einen Versuch mit Startsignal und Handlung für deine echte Woche. Nutze angenehme Pause, passende Bewegung, Faktenprüfung oder Unterstützung nur, wenn das deiner gewählten Handlung hilft.",scope:"Alltagswissen zum Umgang mit Stress für Erwachsene, keine Diagnose oder Behandlung. Hör bei Schwindel, Unbehagen oder Unwohlsein mit Atem- oder Bewegungsübungen auf. Sitze sicher und atme wieder normal. Neue oder beunruhigende körperliche Beschwerden brauchen medizinische Abklärung, bei schweren Beschwerden dringend. Gehe nicht davon aus, dass Panik sie erklärt. Suche fachliche Versorgung bei wiederkehrender Panik, beeinträchtigtem Alltag, Schwierigkeiten beim Zurechtkommen oder erfolgloser Selbsthilfe. Ändere Behandlung oder Medikamente nicht eigenständig. Gedanken an Selbstverletzung brauchen umgehende fachliche Hilfe oder Krisenhilfe. Wenn du deine Sicherheit nicht gewährleisten kannst oder unmittelbar in Gefahr bist, brauchst du örtliche Notfallhilfe. Gewalt braucht Sicherheit und spezialisierte Unterstützung, keine Übung im Aushalten.",outcome:"Eine sichere Handlung für dein Stresszeichen, ehrliche Versuchseinträge und ein machbarer nächster Schritt für die kommende Woche oder Unterstützung.",photo:{id:"1557316655-8715fdecd2d1",alt:"Ruhiger See am Fuß eines Berges"},lessons:t.map((e,n)=>({id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,...r[n],takeaway:e.carry.takeaway,sources:n===0?[...e.goDeeper.sourceIds,"C01"]:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:{title:`Erfundenes Beispiel: ${e.idea.example.title}`,text:e.idea.example.text},photo:s[n]}))},h=Object.freeze(Object.defineProperty({__proto__:null,COURSE:a,LESSONS_V2:t,SOURCES:i},Symbol.toStringTag,{value:"Module"}));export{h as c};
